<script setup lang="ts">
const db=useSupabaseClient()
const user=useSupabaseUser()
const mode=ref<'request'|'signup'>('request')
const schoolName=ref(''),domain=ref(''),code=ref(''),contactName=ref(''),position=ref(''),phone=ref(''),notes=ref('')
const email=ref(''),password=ref(''),busy=ref(false),error=ref(''),message=ref(''),submitted=ref(false)
const requests=ref<any[]>([])
async function load(){if(!user.value)return;const r=await db.from('school_requests').select('id,school_name,school_domain,status,created_at,review_notes').order('created_at',{ascending:false});requests.value=r.data||[]}
watch(user,()=>load(),{immediate:true})
async function signUp(){error.value='';message.value='';busy.value=true;const {error:e}=await db.auth.signUp({email:email.value.trim().toLowerCase(),password:password.value,options:{emailRedirectTo:`${window.location.origin}/request-school`}});busy.value=false;if(e){error.value=e.message;return}message.value='Check your school email and confirm your account. Then sign in to submit your school request.'}
async function submit(){error.value='';message.value='';busy.value=true;const {error:e}=await db.rpc('submit_school_request',{p_school_name:schoolName.value,p_school_domain:domain.value,p_school_code:code.value||null,p_contact_name:contactName.value,p_contact_position:position.value,p_contact_phone:phone.value||null,p_notes:notes.value||null});busy.value=false;if(e){error.value=e.message;return}submitted.value=true;message.value='Request submitted. A platform administrator must verify your authority and approve the school before access is granted.';await load()}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/">← Home</NuxtLink><h1>Request a School</h1><p>Is your school not listed? A school representative can request a new school and become its first School Administrator once approved.</p>
<p class="notice">You must use a verified email address from the school domain you are requesting. No administrator access is granted automatically.</p>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p>
<div v-if="!user" class="card"><h2>School representative account</h2><p>Already have an account? <NuxtLink to="/login?next=request-school"><u>Sign in to request a school</u></NuxtLink></p><button class="btn" type="button" @click="mode=mode==='signup'?'request':'signup'">{{mode==='signup'?'Hide registration':'Create a representative account'}}</button>
<form v-if="mode==='signup'" class="editor" @submit.prevent="signUp"><label>School email<input v-model="email" type="email" required autocomplete="email"></label><label>Password (8+ characters)<input v-model="password" type="password" required minlength="8" autocomplete="new-password"></label><button class="btn" :disabled="busy">{{busy?'Creating…':'Register and verify email'}}</button></form></div>
<template v-else><form v-if="!submitted" class="card editor" @submit.prevent="submit"><h2>School details</h2><label>School name<input v-model="schoolName" required maxlength="150"></label><label>School email domain (without @)<input v-model="domain" required placeholder="school.vic.edu.au" maxlength="253"></label><label>School code (optional)<input v-model="code" maxlength="30"></label><h2>Proposed School Administrator</h2><p>Your verified account email: <strong>{{user.email}}</strong></p><label>Full name<input v-model="contactName" required maxlength="150"></label><label>Position at school<input v-model="position" required maxlength="120" placeholder="e.g. Sports Coordinator"></label><label>Contact phone (optional)<input v-model="phone" maxlength="50"></label><label>Additional information<textarea v-model="notes" maxlength="2000" rows="3" placeholder="Details to help us verify your request"></textarea></label><button class="btn" :disabled="busy">{{busy?'Submitting…':'Submit School Request'}}</button></form>
<div v-if="requests.length" class="card"><h2>My School Requests</h2><div v-for="r in requests" :key="r.id" class="data-row"><div><strong>{{r.school_name}}</strong> · @{{r.school_domain}}<p>Status: {{r.status}}</p><p v-if="r.review_notes">Review notes: {{r.review_notes}}</p></div></div></div></template></div></div></template>
